function C:__fields()
  if C.super and C.super.__fields then C.super.__fields(self) end
  self.ZIPCOUNT = 30
  self.chooseZip = nil
  self._open = nil
  self._continue = nil
  self._zip = nil
  self._picture = nil
  self._openNum = nil
  self._zipObjs = NEW("List", nil)
end

C.__getters["ChoosingZip"] = function(self)
  return self.chooseZip.activeInHierarchy
end
C.__getters["SelectableObjects"] = function(self)
  return self._zipObjs
end
C.__getters["ContinueObj"] = function(self)
  return self._continue.gameObject
end
function C:Start()
  self:startChooseZip()
end

function C:startChooseZip()
  self.chooseZip:SetActive(true)
  local active = true
  do
    local i = 1
    while i <= self.ZIPCOUNT do
      local z = Object.Instantiate(self._zip, self.chooseZip.transform):GetComponent("EndingZip")
      local flag = Settings.unLockedZip:Contains(i)
      z:setData(i, flag)
      if not flag then
        active = false
      end
      if not z.isEmpty then
        z.button:OnClickAsObservable():Subscribe(function(_)
          self:startOpen(z.zipNumber)
        end):AddTo(z)
      end
      self._zipObjs:Add(z.gameObject)
      i = i + 1
    end
  end
  self._continue.gameObject:SetActive(active)
  self._continue:OnClickAsObservable():Subscribe(function(_)
    SceneManager.LoadScene("BiosToLoad")
  end):AddTo(self._continue)
end

function C:startOpen(zipnumber)
  if not coroutine.isyieldable() then spawn(C.startOpen, self, zipnumber) return end
  AudioManager:PlaySeByType("SE_piporo", false)
  self.chooseZip:SetActive(false)
  self._open:SetActive(true)
  self._openNum.text = TOSTR(zipnumber)
  local resources = ImageViewerHelper.LoadFanArtList()
  local imageIdList = NEW("List", nil)
  do
    local i = zipnumber - 1
    while i < resources.Count do
      local component = Object.Instantiate(self._picture, self._open.transform):GetComponent("MyPictureContentView")
      local resourceLocal = IDX(resources, i)
      local contentStatic = INIT(NEW("MyPictureContent", 1), { Id = resourceLocal.Id, Title = resourceLocal.Id, FileName = resourceLocal.FileName })
      spawn(function() component:SetContentStatic(contentStatic) end)
      imageIdList:Add(resourceLocal.FileName)
      AudioManager:PlaySeByType("SE_tweet_load", false)
      UniTask.Delay(120, false, "Update", nil, false)
      i = i + self.ZIPCOUNT
    end
  end
  Settings:OpenZip(zipnumber, imageIdList)
  self._continue.gameObject:SetActive(true)
  self._continue:OnClickAsObservable():Subscribe(function(_)
    SceneManager.LoadScene("BiosToLoad")
  end):AddTo(self._continue)
end

return C
